async def validate_phase_checkpoint(checkpoint):
    """Auto-validate phase completion criteria."""
    validation = checkpoint['validation']
    failures = []

    # Validate test pass rate
    if 'test_pass_rate' in validation:
        result = await run_test_suite()
        if result.pass_rate < validation['test_pass_rate']:
            failures.append(f"Test pass rate: {result.pass_rate} < {validation['test_pass_rate']}")

    # Validate performance budgets
    if 'performance_under_budget' in validation:
        result = await run_performance_tests()
        if not result.all_budgets_met:
            failures.append(f"Performance budgets not met: {result.violations}")

    if failures:
        raise CheckpointValidationError(
            f"Phase {checkpoint['after_phase']} validation failed:\n"
            + "\n".join(f"  - {f}" for f in failures)
        )

    return Ok("Phase validation passed")
